package knowledge

import "github.com/sdskill/archintel/pkg/model"

// RiskLevel indicates the operational or data severity of an anti-pattern.
type RiskLevel string

const (
	RiskCritical RiskLevel = "CRITICAL" // Leads to data loss, pool exhaustion, or severe downtime
	RiskHigh     RiskLevel = "HIGH"     // Severe latency degradation or operational failure
	RiskMedium   RiskLevel = "MEDIUM"   // Unnecessary cognitive and deployment complexity
)

// AntiPattern represents a dangerous or overengineered design pattern frequently
// generated by AI coding agents.
type AntiPattern struct {
	// ID is the unique anti-pattern identifier (e.g. "ANTI-SYNC-IN-TX").
	ID string `json:"id"`

	// Name is the human-readable title.
	Name string `json:"name"`

	// Risk is the severity of this anti-pattern.
	Risk RiskLevel `json:"risk"`

	// Description explains why AI coding agents generate this and what goes wrong.
	Description string `json:"description"`

	// WhyItFails explains the technical failure mechanism (e.g. connection pool exhaustion).
	WhyItFails string `json:"why_it_fails"`

	// Remediation provides the correct architectural alternative.
	Remediation string `json:"remediation"`
}

// AntiPatternCatalog manages curated anti-patterns.
type AntiPatternCatalog struct {
	items map[string]AntiPattern
}

// NewAntiPatternCatalog initializes the default curated anti-pattern repository.
func NewAntiPatternCatalog() *AntiPatternCatalog {
	c := &AntiPatternCatalog{
		items: make(map[string]AntiPattern),
	}
	c.seed()
	return c
}

func (c *AntiPatternCatalog) seed() {
	list := []AntiPattern{
		{
			ID:          "ANTI-SYNC-IN-TX",
			Name:        "Synchronous External HTTP Call Inside Database Transaction",
			Risk:        RiskCritical,
			Description: "Invoking external payment, email, or webhook APIs while holding an active database transaction.",
			WhyItFails:  "Third-party network latency holds open database connections and locks, rapidly exhausting the connection pool and causing cascading service outage.",
			Remediation: "Commit the local database transaction first (recording an event in a Transactional Outbox table), then dispatch the external HTTP call asynchronously from a worker.",
		},
		{
			ID:          "ANTI-UNBOUNDED-WORKERS",
			Name:        "Unbounded Goroutine or Thread Dispatch",
			Risk:        RiskCritical,
			Description: "Spawning a new goroutine (e.g. 'go handle()') for every incoming request or background task without a semaphore or worker pool.",
			WhyItFails:  "During traffic spikes, thousands of concurrent goroutines exhaust RAM, CPU, and database connection pools, crashing the process.",
			Remediation: "Use a bounded worker pool or channel semaphore with explicit queue buffer capacity and backpressure.",
		},
		{
			ID:          "ANTI-DISTRIBUTED-2PC",
			Name:        "Distributed 2-Phase Commit (2PC) Across Microservices",
			Risk:        RiskCritical,
			Description: "Attempting synchronous distributed ACID transactions across multiple microservice databases.",
			WhyItFails:  "Extremely fragile under network partitions; locks multiple remote databases, creating high latency, deadlocks, and blocking.",
			Remediation: "Prefer a Modular Monolith sharing a single transactional DB, or use Saga orchestration with compensation workflows for distributed boundaries.",
		},
		{
			ID:          "ANTI-QUEUE-WITHOUT-SKIP-LOCKED",
			Name:        "Database Job Queue Without SKIP LOCKED",
			Risk:        RiskHigh,
			Description: "Using a SQL table as a queue with standard 'SELECT ... LIMIT 1' and 'UPDATE' without row-level skip-locked semantics.",
			WhyItFails:  "Multiple concurrent workers contend for the same row, leading to race conditions, double processing, or sequential lock serialization bottlenecks.",
			Remediation: "Use 'SELECT ... FOR UPDATE SKIP LOCKED' or a dedicated message queue when throughput exceeds DB limits.",
		},
		{
			ID:          "ANTI-PREMATURE-MICROSERVICES",
			Name:        "Premature Microservices Architecture",
			Risk:        RiskMedium,
			Description: "Splitting an early-stage or low-throughput application into dozens of small services and repositories.",
			WhyItFails:  "Multiplies deployment complexity, network overhead, cross-service debugging difficulty, and distributed failure modes without any scale justification.",
			Remediation: "Adopt a clean Modular Monolith. Decouple packages through interfaces while maintaining a single deployable artifact and unified database.",
		},
	}

	for _, ap := range list {
		c.items[ap.ID] = ap
	}
}

// Get returns an anti-pattern by ID.
func (c *AntiPatternCatalog) Get(id string) (*AntiPattern, bool) {
	ap, ok := c.items[id]
	if !ok {
		return nil, false
	}
	return &ap, true
}

// All returns all anti-patterns.
func (c *AntiPatternCatalog) All() []AntiPattern {
	var list []AntiPattern
	for _, ap := range c.items {
		list = append(list, ap)
	}
	return list
}

// RelevantAntiPatterns detects anti-patterns particularly hazardous for the given requirements.
func (c *AntiPatternCatalog) RelevantAntiPatterns(req *model.NormalizedRequirements) []AntiPattern {
	var relevant []AntiPattern

	// In transaction-heavy / ecommerce / fintech workloads, synchronous calls in tx and distributed 2PC are fatal risks.
	if req.Domain == model.DomainECommerce || req.Domain == model.DomainFinTech || req.Data.RequiresACID {
		if ap, ok := c.Get("ANTI-SYNC-IN-TX"); ok {
			relevant = append(relevant, *ap)
		}
		if ap, ok := c.Get("ANTI-DISTRIBUTED-2PC"); ok {
			relevant = append(relevant, *ap)
		}
	}

	// For all workloads, unbounded workers and premature microservices must be flagged.
	if ap, ok := c.Get("ANTI-UNBOUNDED-WORKERS"); ok {
		relevant = append(relevant, *ap)
	}

	if !req.HasHighThroughput() {
		if ap, ok := c.Get("ANTI-PREMATURE-MICROSERVICES"); ok {
			relevant = append(relevant, *ap)
		}
	}

	return relevant
}
